export const FULL_CAPACITY_SOURCE_PINS=Object.freeze(Object.fromEntries(Object.entries(rows).map(([path,row])=>[path,{before:row.parentSha256,after:row.candidateSha256}])));
export function projectFullCapacitySourceToParent(path,value){const row=rows[path];assert.ok(row,'FULL_CAPACITY_SOURCE_PATH');assert.equal(sha(value),row.candidateSha256,'FULL_CAPACITY_SOURCE_PIN:'+path);for(const hunk of row.reverseHunks){assert.equal(value.split(hunk.from).length,2,'FULL_CAPACITY_HUNK_UNIQUE:'+path);value=value.replace(hunk.from,hunk.to);}assert.equal(sha(value),row.parentSha256,'FULL_CAPACITY_FULL_PARENT:'+path);return value;}
